INSERT INTO `articles` (`id`, `blog_class`, `title`, `count`, `create_time`, `type_name`, `html_content`, `created_at`, `updated_at`, `status`) VALUES (451, '36', 'HTTP 协议', 111, '2024-02-22 00:00:00', '浏览器', '<h2>Https</h2><p>概念HTTP（hypertext transport protocol）协议；</p><p>中文叫超文本传输协议是一种基于TCP/IP的应用层通信协议。</p>', '2026-02-04 09:01:52', '2026-02-21 09:14:48', 'draft');
INSERT INTO `articles` (`id`, `blog_class`, `title`, `count`, `create_time`, `type_name`, `html_content`, `created_at`, `updated_at`, `status`) VALUES (452, '42', 'Node.js + Docker自动化部署', 68, '2024-08-26 00:00:00', 'docker', '<p>本章将介绍 Node.js 使用 Docker 、nodejs自动化部署、蓝绿部署、项目到服务器。哈哈哈</p>', '2026-02-04 09:01:52', '2026-02-21 09:14:52', 'draft');
INSERT INTO `articles` (`id`, `blog_class`, `title`, `count`, `create_time`, `type_name`, `html_content`, `created_at`, `updated_at`, `status`) VALUES (453, '0', 'Langchain - Get started', 35, '2026-02-04 20:04:44', 'Langchain', '<h1>Getting started</h1><p>Welcome to the <em><mark>Simple Editor</mark></em> template! This template integrates <strong>open source</strong> UI components and Tiptap extensions licensed under <strong>MIT</strong>.</p><p>Integrate it by following the <a target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"https://tiptap.dev/docs/ui-components/templates/simple-editor\">Tiptap UI Components docs</a> or using our CLI tool.</p><pre><code>npx @tiptap/cli init</code></pre><h2>Features</h2><blockquote><p><em>A fully responsive rich text editor with built-in support for common formatting and layout tools. Type markdown </em><code>**</code><em> or use keyboard shortcuts </em><code>⌘+B</code> for <s>most</s> all common markdown marks. 🪄</p></blockquote><p style=\"text-align: left;\">Add images, customize alignment, and apply <mark>advanced formatting</mark> to make your writing more engaging and professional.</p><p></p><img src=\"data:image/jpeg;base64,\" style=\"width: 305px; margin: 0px auto; display: block;\"><ul><li><p style=\"text-align: left;\"><strong>Superscript</strong> (x<sup>2</sup>) and <strong>Subscript</strong> (H<sub>2</sub>O) for precision.</p></li></ul><ul><li><p style=\"text-align: left;\"><strong>Typographic conversion</strong>: automatically convert to <code>-&gt;</code> an arrow <strong>→</strong>.</p></li></ul><p style=\"text-align: left;\"><em>→ </em><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"https://tiptap.dev/docs/ui-components/templates/simple-editor#features\">Learn more</a></p><hr><h2 style=\"text-align: left;\">Make it your own</h2><p style=\"text-align: left;\">Switch between light and dark modes, and tailor the editor\'s appearance with customizable CSS to match your style.</p><ul data-type=\"taskList\"><li data-checked=\"true\" data-type=\"taskItem\"><label><input type=\"checkbox\" checked=\"checked\"><span></span></label><div><p style=\"text-align: left;\">Test template</p></div></li><li data-checked=\"false\" data-type=\"taskItem\"><label><input type=\"checkbox\"><span></span></label><div><p style=\"text-align: left;\"><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"https://tiptap.dev/docs/ui-components/templates/simple-editor\">Integrate the free template</a></p></div></li></ul><p style=\"text-align: left;\"></p>', '2026-02-04 12:04:44', '2026-02-21 11:20:35', 'draft');
